// ============================================================
// logoData.js
// The real Zeep Broad Brand logo, embedded directly as base64 so it
// always renders no matter how the static /public folder is served or
// cached on a given deployment - no separate image file to go missing
// or 404. The white background has been made transparent and the
// image trimmed to its content, so it sits cleanly on dark backgrounds
// instead of showing a white box.
//
// LOGO_DATA_URI / LOGO_ICON_DATA_URI - original colors (dark charcoal
//   icon + black text, gold accents). Used on the login screen, whose
//   card background is light by default.
// LOGO_SIDEBAR_DATA_URI / LOGO_SIDEBAR_ICON_DATA_URI - same artwork
//   with the dark charcoal/black areas recolored to a light cream so
//   they stay readable against the sidebar's dark navy/black
//   background (which never switches to a light background, even in
//   light mode) - gold accents are untouched.
// LOGO_FAVICON_DATA_URI - small 32x32 version for the browser tab icon.
// ============================================================

export const LOGO_DATA_URI = 'data:image/png;base64,';

export const LOGO_ICON_DATA_URI = 'data:image/png;base64,';

export const LOGO_SIDEBAR_DATA_URI = 'data:image/png;base64,';

export const LOGO_SIDEBAR_ICON_DATA_URI = 'data:image/png;base64,';

export const LOGO_FAVICON_DATA_URI = 'data:image/png;base64,';
